#include <algorithm>
#include <cstdio>
#include <string>
#include <vector>
using namespace std;

class FastInput {
    static const int SIZE = 1 << 16;
    char buffer[SIZE];
    int index = 0, length = 0;

    char getChar() {
        if (index >= length) {
            length = static_cast<int>(fread(buffer, 1, SIZE, stdin));
            index = 0;
            if (length == 0) return '\0';
        }
        return buffer[index++];
    }

public:
    bool readInt(int& value) {
        char c;
        do {
            c = getChar();
            if (!c) return false;
        } while (c <= ' ');

        int sign = 1;
        if (c == '-') {
            sign = -1;
            c = getChar();
        }

        value = 0;
        while (c >= '0' && c <= '9') {
            value = value * 10 + (c - '0');
            c = getChar();
        }
        value *= sign;
        return true;
    }

    bool readWord(string& value) {
        char c;
        do {
            c = getChar();
            if (!c) return false;
        } while (c <= ' ');

        value.clear();
        while (c > ' ') {
            value.push_back(c);
            c = getChar();
        }
        return true;
    }
};

struct Statement {
    int left;
    int right;
    int parity;
};

class DSU {
    vector<int> parent;
    vector<int> size;
    vector<int> parity;

public:
    explicit DSU(int n) : parent(n), size(n, 1), parity(n, 0) {
        for (int i = 0; i < n; ++i) parent[i] = i;
    }

    int find(int x) {
        if (parent[x] == x) return x;
        int oldParent = parent[x];
        parent[x] = find(oldParent);
        parity[x] ^= parity[oldParent];
        return parent[x];
    }

    bool unite(int x, int y, int requiredParity) {
        int rootX = find(x);
        int rootY = find(y);
        int relation = parity[x] ^ parity[y] ^ requiredParity;

        if (rootX == rootY)
            return (parity[x] ^ parity[y]) == requiredParity;

        if (size[rootX] < size[rootY]) {
            parent[rootX] = rootY;
            parity[rootX] = relation;
            size[rootY] += size[rootX];
        } else {
            parent[rootY] = rootX;
            parity[rootY] = relation;
            size[rootX] += size[rootY];
        }
        return true;
    }
};

int main() {
    FastInput input;
    int n, m;
    if (!input.readInt(n) || !input.readInt(m)) return 0;

    vector<Statement> statements(m);
    vector<int> coordinates;
    coordinates.reserve(2 * m);

    for (int i = 0; i < m; ++i) {
        string type;
        input.readInt(statements[i].left);
        input.readInt(statements[i].right);
        input.readWord(type);

        statements[i].parity = !type.empty() && type[0] == 'o';
        coordinates.push_back(statements[i].left - 1);
        coordinates.push_back(statements[i].right);
    }

    sort(coordinates.begin(), coordinates.end());
    coordinates.erase(unique(coordinates.begin(), coordinates.end()),
                      coordinates.end());

    DSU dsu(static_cast<int>(coordinates.size()));

    for (int i = 0; i < m; ++i) {
        int x = static_cast<int>(
            lower_bound(coordinates.begin(), coordinates.end(),
                        statements[i].left - 1) - coordinates.begin());
        int y = static_cast<int>(
            lower_bound(coordinates.begin(), coordinates.end(),
                        statements[i].right) - coordinates.begin());

        if (!dsu.unite(x, y, statements[i].parity)) {
            printf("%d", i);
            return 0;
        }
    }

    printf("%d", m);
    return 0;
}

