struct Statement {
    int l, r, parity;
};

class DSU {
    vector<int> parent, rank_, parity;

public:
    explicit DSU(int n) : parent(n), rank_(n, 0), parity(n, 0) {
        iota(parent.begin(), parent.end(), 0);
    }

    int find(int x) {
        if (parent[x] == x) return x;
        int p = parent[x];
        parent[x] = find(p);
        parity[x] ^= parity[p];
        return parent[x];
    }

    bool unite(int x, int y, int value) {
        int rx = find(x);
        int px = parity[x];
        int ry = find(y);
        int py = parity[y];

        if (rx == ry)
            return (px ^ py) == value;

        if (rank_[rx] < rank_[ry]) {
            parent[rx] = ry;
            parity[rx] = px ^ py ^ value;
        } else {
            parent[ry] = rx;
            parity[ry] = px ^ py ^ value;
            if (rank_[rx] == rank_[ry]) ++rank_[rx];
        }
        return true;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;

    vector<Statement> statements(m);
    vector<int> coordinates;
    coordinates.reserve(2 * m);

    for (auto& statement : statements) {
        string type;
        cin >> statement.l >> statement.r >> type;
        statement.parity = (type[0] == 'o');
        coordinates.push_back(statement.l - 1);
        coordinates.push_back(statement.r);
    }

    sort(coordinates.begin(), coordinates.end());
    coordinates.erase(unique(coordinates.begin(), coordinates.end()),
                      coordinates.end());

    DSU dsu(static_cast<int>(coordinates.size()));

    for (int i = 0; i < m; ++i) {
        int x = lower_bound(coordinates.begin(), coordinates.end(),
                            statements[i].l - 1) - coordinates.begin();
        int y = lower_bound(coordinates.begin(), coordinates.end(),
                            statements[i].r) - coordinates.begin();

        if (!dsu.unite(x, y, statements[i].parity)) {
            cout << i;
            return 0;
        }
    }

    cout << m;
    return 0;
}

